mapper.select:
/* PaperPermissionAdminMapper.selectTeacherPage */

WHERE u.tc_id IS NOT NULL
  AND u.status = 'ACTIVE'
ORDER BY u.user_no DESC
LIMIT #{limit} OFFSET #{offset}

/* PaperPermissionAdminMapper.selectTeachersBySpUserIds */

WHERE u.tc_id IS NOT NULL
  AND u.status = 'ACTIVE'
  AND u.sp_user_id IN
  #{id}
